import { useState, useEffect } from "react";
import CompanyLayout from "./CompanyLayout";
import axios from "axios";

// الإبقاء على STATUS_CFG كما هي للتنسيق
const STATUS_CFG = {
  pending: { badge: "badge-orange", label: "Pending", icon: "⏳" },
  accepted: { badge: "badge-green", label: "Accepted", icon: "✅" },
  rejected: { badge: "badge-red", label: "Rejected", icon: "❌" },
};

export default function CompanyCandidates() {
  const [candidates, setCandidates] = useState([]); // مصفوفة فارغة في البداية
  const [loading, setLoading] = useState(true);
  
  const [filterStatus, setFilterStatus] = useState("all");
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState(null);
  

  // 1. جلب البيانات من الباكيند عند تحميل الصفحة
  useEffect(() => {
    const fetchApplications = async () => {
      try {
        const token = localStorage.getItem('access_token');
        const response = await axios.get('http://127.0.0.1:8000/api/company/applications/', {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        setCandidates(response.data);
        setLoading(false);
      } catch (error) {
        console.error("Error fetching applications:", error);
        setLoading(false);
      }
    };
    fetchApplications();
  }, []);

  // 2. دالة تحديث حالة الطلب (قبول/رفض) في الباكيند
  const handleDecide = async (id, status, note) => {
    try {
      const token = localStorage.getItem('access_token');
      // نفترض وجود Endpoint لتحديث الحالة مثل /api/applications/{id}/update/
      await axios.patch(`http://127.0.0.1:8000/api/applications/${id}/`, 
        { status, note },
        { headers: { 'Authorization':` Bearer ${token} `} }
      );

      // تحديث الحالة في الواجهة محلياً بعد نجاح طلب الباكيند
      setCandidates(prev => prev.map(c => c.id === id ? { ...c, status, note } : c));
      if (selected?.id === id) setSelected(prev => ({ ...prev, status, note }));
    } catch (error) {
      alert("حدث خطأ أثناء تحديث الحالة");
    }
  };

  // تصفية البيانات (Filtering)
  const filtered = candidates.filter(c => {
    
    const matchStatus = filterStatus === "all" || c.status === filterStatus;
    const matchSearch = !search || 
                       c.student_name.toLowerCase().includes(search.toLowerCase());
    return matchOffer && matchStatus && matchSearch;
  });

  const pendingCount = candidates.filter(c => c.status === "pending").length;

  if (loading) return <div className="p-10 text-center">Loading candidates...</div>;

  return (
    <CompanyLayout active="candidates" pendingCount={pendingCount}>
      <div className="p-5 md:p-8">
        {/* العناوين والفلترة */}
        <div className="anim-fade-up mb-6">
          <p className="text-xs font-semibold text-blue-500 uppercase tracking-widest mb-1">Candidates</p>
          <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl tracking-tight">Candidate tracking</h1>
          <p className="text-slate-400 text-sm font-light mt-0.5">{candidates.length} total · <span className="text-amber-600 font-medium">{pendingCount} pending review</span></p>
        </div>

        {/* Filters */}
        <div className="anim-fade-up anim-d1 card border border-slate-200 p-4 mb-5">
          <div className="flex flex-col md:flex-row gap-3">
            <input type="text" placeholder="Search by name..." value={search} onChange={e => setSearch(e.target.value)} className="input-field flex-1" />
            
            <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="input-field md:w-40">
              <option value="all">All statuses</option>
              <option value="pending">Pending</option>
              <option value="accepted">Accepted</option>
              <option value="rejected">Rejected</option>
            </select>
          </div>
        </div>
        <div className="grid md:grid-cols-5 gap-5">
          {/* قائمة المترشحين */}
          <div className="md:col-span-2 space-y-2">
            {filtered.map(c => (
              <div key={c.id} onClick={() => setSelected(c)} className={`card border candidate-row p-4 cursor-pointer ${selected?.id === c.id ? "selected border-blue-300 shadow-sm" : "border-slate-200"}`}>
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-blue-600 flex items-center justify-center text-sm font-bold text-white">
                    {c.student_name[0]}
                  </div>
                  <div className="flex-1">
                    <div className="font-semibold text-sm text-slate-800">{c.student_name}</div>
                    <div className="text-xs text-slate-400">{c.offer_title}</div>
                  </div>
                  <span className={`badge ${STATUS_CFG[c.status].badge}`}>{STATUS_CFG[c.status].label}</span>
                </div>
              </div>
            ))}
          </div>

          {/* تفاصيل المترشح المختار */}
          <div className="md:col-span-3">
            {selected ? (
              <div className="card border border-slate-200 p-5 sticky top-4">
                <h2 className="font-syne font-extrabold text-slate-900 text-xl">{selected.student_name}</h2>
                <p className="text-slate-500 text-sm mb-4">{selected.student_email}</p>
                
                <div className="bg-blue-50 p-3 rounded-xl mb-5">
                  <div className="text-xs text-blue-500 font-semibold uppercase">Applied for</div>
                  <div className="text-sm font-semibold text-slate-800">{selected.offer_title}</div>
                </div>

                {selected.status === "pending" ? (
                  <div className="flex gap-2">
                     <button onClick={() => handleDecide(selected.id, 'accepted', 'Accepted through dashboard')} className="accept-btn flex-1 text-white py-2 rounded-lg">Accept</button>
                     <button onClick={() => handleDecide(selected.id, 'rejected', 'Does not match requirements')} className="reject-btn flex-1 text-white py-2 rounded-lg">Reject</button>
                  </div>
                ) : (
                  <div className="p-4 rounded-xl bg-slate-100 text-center font-bold">
                    Decision: {selected.status.toUpperCase()}
                  </div>
                )}
              </div>
            ) : (
              <div className="text-center p-10 border border-dashed border-slate-300 rounded-xl">
                Select a candidate to view details
              </div>
            )}
          </div>
        </div>
      </div>
    </CompanyLayout>
  );
}
